package worldgen

import (
	"atlas/internal/blockstate"
	"bufio"
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"encoding/binary"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

// TestTerrainStageDiagnostic is an opt-in development probe. Its inputs are
// generated by docs/worldgen/diagnose_terrain_stages.py; ordinary suites skip it.
// Structures are deliberately disabled, matching the existing native probes.
func TestTerrainStageDiagnostic(t *testing.T) {
	dir := os.Getenv("ATLAS_TERRAIN_DIAG_DIR")
	if dir == "" {
		t.Skip("ATLAS_TERRAIN_DIAG_DIR is not set")
	}
	type key struct {
		seed   int64
		cx, cz int32
	}
	type vectors struct{ noise, surface, carved, mask []byte }
	cases := make(map[key]*vectors)
	for _, filename := range []string{"noise.txt", "surface.txt", "carved.txt"} {
		file, err := os.Open(filepath.Join(dir, filename))
		if err != nil {
			t.Fatal(err)
		}
		scanner := bufio.NewScanner(file)
		scanner.Buffer(make([]byte, 65536), 4*1024*1024)
		for scanner.Scan() {
			fields := strings.Fields(scanner.Text())
			if len(fields) == 0 || fields[0] == "density" {
				continue
			}
			wantFields := map[string]int{"chunk": 5, "surface_chunk": 6, "carved_chunk": 13}[fields[0]]
			if wantFields == 0 || len(fields) != wantFields {
				t.Fatalf("invalid diagnostic line in %s", filename)
			}
			parse := func(i, bits int) int64 {
				n, err := strconv.ParseInt(fields[i], 10, bits)
				if err != nil {
					t.Fatal(err)
				}
				return n
			}
			k := key{parse(1, 64), int32(parse(2, 32)), int32(parse(3, 32))}
			v := cases[k]
			if v == nil {
				v = &vectors{}
				cases[k] = v
			}
			decode := func(i, size int) []byte {
				compressed, err := base64.StdEncoding.DecodeString(fields[i])
				if err != nil {
					t.Fatal(err)
				}
				r, err := gzip.NewReader(bytes.NewReader(compressed))
				if err != nil {
					t.Fatal(err)
				}
				data, err := io.ReadAll(io.LimitReader(r, int64(size+1)))
				r.Close()
				if err != nil || len(data) != size {
					t.Fatalf("invalid diagnostic payload: size %d want %d: %v", len(data), size, err)
				}
				return data
			}
			switch fields[0] {
			case "chunk":
				v.noise = decode(4, 16*16*384*3)
			case "surface_chunk":
				if fields[4] != "natural" {
					t.Fatal("diagnostic expects natural biome")
				}
				v.surface = decode(5, 16*16*384*2)
			case "carved_chunk":
				v.carved = decode(12, 16*16*384*2)
				v.mask = decode(11, 16*16*384/8)
			}
		}
		file.Close()
		if err := scanner.Err(); err != nil {
			t.Fatal(err)
		}
	}
	if len(cases) == 0 || len(cases) > 9 {
		t.Fatalf("diagnostic requires 1 to 9 chunks, got %d", len(cases))
	}
	for k, v := range cases {
		t.Run(fmt.Sprintf("%d/%d,%d", k.seed, k.cx, k.cz), func(t *testing.T) {
			if v.noise == nil || v.surface == nil || v.carved == nil || v.mask == nil {
				t.Fatal("all native stages are required")
			}
			g, err := NewOverworldNoiseGenerator(k.seed)
			if err != nil {
				t.Fatal(err)
			}
			biomes, err := NewOverworldBiomeSampler(k.seed)
			if err != nil {
				t.Fatal(err)
			}
			chunk, err := g.GenerateNoise(k.cx, k.cz)
			if err != nil {
				t.Fatal(err)
			}
			states := func(chunk *NoiseChunkResult) []byte {
				data := make([]byte, len(chunk.Blocks)*2)
				ids := make(map[string]uint32)
				for i := range chunk.Blocks {
					s, err := chunk.BlockStateAt(int32(i%16), int32(i/256)+chunk.MinY, int32(i/16%16))
					if err != nil {
						t.Fatal(err)
					}
					name := fmt.Sprint(s)
					id, found := ids[name]
					if !found {
						id, err = blockstate.BlockStateID(s.Name, s.Properties)
						if err != nil {
							t.Fatal(err)
						}
						ids[name] = id
					}
					binary.BigEndian.PutUint16(data[i*2:], uint16(id))
				}
				return data
			}
			compare := func(stage string, got, want []byte, stride int) {
				differences, wetDifferences := 0, 0
				for i := range chunk.Blocks {
					a, b := binary.BigEndian.Uint16(got[i*2:]), binary.BigEndian.Uint16(want[i*stride:])
					if a != b {
						if differences < 8 {
							t.Logf("%s difference at %d,%d,%d: Go state %d, native state %d", stage,
								k.cx*16+int32(i%16), int32(i/256)-64, k.cz*16+int32(i/16%16), a, b)
						}
						differences++
						if y := int32(i/256) - 64; y >= 40 && y <= 80 {
							wetDifferences++
						}
					}
				}
				t.Logf("%s state differences=%d/98304, differences at Y40..80=%d", stage, differences, wetDifferences)
				if differences != 0 {
					t.Errorf("%s differs from native", stage)
				}
				path := filepath.Join(dir, fmt.Sprintf("go-%d-%d-%s.states", k.cx, k.cz, stage))
				if err := os.WriteFile(path, got, 0644); err != nil {
					t.Fatal(err)
				}
			}
			compare("noise", states(chunk), v.noise, 3)
			fluidDiff := 0
			for i, flag := range chunk.FluidUpdates {
				if flag != (v.noise[i*3+2] != 0) {
					fluidDiff++
				}
			}
			t.Logf("noise fluid update differences=%d", fluidDiff)
			if fluidDiff != 0 {
				t.Error("noise fluid updates differ from native")
			}
			if err := g.ApplySurface(chunk, biomes.BiomeAtQuart); err != nil {
				t.Fatal(err)
			}
			compare("surface", states(chunk), v.surface, 2)
			if err := g.ApplyCarvers(chunk, biomes.BiomeAtQuart); err != nil {
				t.Fatal(err)
			}
			compare("carved", states(chunk), v.carved, 2)
			maskDiff := 0
			for i, bit := range chunk.CarvingMask {
				if bit != (v.mask[i/8]&(1<<uint(i%8)) != 0) {
					maskDiff++
				}
			}
			t.Logf("carving mask differences=%d", maskDiff)
			if maskDiff != 0 {
				t.Error("carving masks differ from native")
			}
			runtime, err := NewOverworldGenerator(k.seed)
			if err != nil {
				t.Fatal(err)
			}
			base, err := runtime.generateBase(k.cx, k.cz)
			if err != nil {
				t.Fatal(err)
			}
			compare("integrated-base", states(base.terrain), v.carved, 2)
		})
	}
}
